// Plan 51 / Migration 189 (Koordinator 31.10.2026): Buchungen ohne Preis zeigen „Kosten unbekannt“ statt 0 €; Summen mit einem unbekannten Teil zeigen den
// bekannten Betrag mit dem Zusatz „dazu N Aufrufe ohne Preis (Kosten unbekannt)“. ohne_preis/aufrufe kommen aus der Datenbank (Migration 189).
const KU_n = x => Math.max(0, Number((x || {}).ohne_preis) || 0);
const KU_alle = x => KU_n(x) > 0 && KU_n(x) >= (Number((x || {}).aufrufe) || 0);
const KU_t = n => n.toLocaleString('de-DE') + (n === 1 ? ' Aufruf' : ' Aufrufe') + ' ohne Preis';
const KU_dazu = n => 'dazu ' + KU_t(n) + ' (Kosten unbekannt)';
const KU_wert = (x, betrag) => KU_alle(x) ? 'Kosten unbekannt (' + KU_t(KU_n(x)) + ')' : KU_n(x) ? betrag + ' · ' + KU_dazu(KU_n(x)) : betrag;
// KI-Verbrauch (ALLY 35, BA5, Stefan 20.10.2026): Seite aus dem Kopf. Verbrauch des Monats, Budget, Stand, Kosten je Funktion (Tabelle, sortierbar).
// Daten wie ALLY 8: ki_monat_stand, ki_monat_funktionen. Zahnrad (nur Admin) → Einstellungen › KI und Budget (S3.2/S3.3). Liefert nur die Seitenbeschreibung (JSON).
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const titel = String(F.name || 'KI-Verbrauch');
const kopf = { schluessel: 'ki-verbrauch', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
if (D.admin === true && /^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || ''))) kopf.zahnrad = { ziel: { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } };
const st = D.stand && typeof D.stand === 'object' ? D.stand : null;
if (D.ok !== true || !st) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Der KI-Verbrauch konnte nicht geladen werden. Bitte neu laden.' }] } } }];
const z = (v, n) => v === null || v === undefined || v === '' || isNaN(Number(v)) ? '–' : Number(v).toLocaleString('de-DE', { minimumFractionDigits: n, maximumFractionDigits: n });
const eur = st.verbrauch_eur !== null && st.verbrauch_eur !== undefined;
const STUFE = { ok: ['Im Rahmen', ''], hinweis: ['Warnschwelle erreicht', 'warn'], sparen: ['Sparmodus aktiv', 'warn'], gesperrt: ['Budget aufgebraucht', 'warn'], ueber_budget: ['Budget überschritten', 'warn'] };
const stufe = STUFE[st.stufe] || STUFE.ok;
const monat = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', month: 'long', year: 'numeric' }).format(new Date());
const ueberblick = { kennzahlen: [
  { label: 'Verbrauch ' + monat, wert: KU_alle(st) ? 'Kosten unbekannt' : eur ? z(st.verbrauch_eur, 2) + ' €' : z(st.verbrauch_usd, 2) + ' US-$',
    neben: KU_alle(st) ? KU_t(KU_n(st)) : [eur ? z(st.verbrauch_usd, 2) + ' US-$' : '', KU_n(st) ? KU_dazu(KU_n(st)) : ''].filter(Boolean).join(' · '), ...(KU_n(st) ? { ton: 'warn' } : {}) },
  { label: 'Budget im Monat', wert: st.budget_eur !== null && st.budget_eur !== undefined ? z(st.budget_eur, 2) + ' €' : 'keine Grenze', neben: '' },
  { label: 'Verbraucht', wert: st.prozent !== null && st.prozent !== undefined ? z(st.prozent, 1) + ' %' : '–', neben: '', ton: stufe[1] },
  { label: 'Stand', wert: stufe[0], neben: '', ton: stufe[1] }],
  karten: [
    { titel: 'Offen', leer: 'Nichts offen.', eintraege: st.stufe && st.stufe !== 'ok' ? [Object.assign({ marke: { text: stufe[0], ton: 'warn' },
      text: st.stufe === 'gesperrt' ? 'KI-Aufgaben sind bis zum Monatsende gestoppt.' : st.stufe === 'sparen' ? 'Für KI-Aufgaben wird ein günstigeres Modell genutzt.' : 'Das Budget für diesen Monat ist fast oder ganz erreicht.' },
      D.admin === true && kopf.zahnrad ? { ziel: kopf.zahnrad.ziel, ziel_text: 'Budget' } : {})] : [] },
    { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: [].concat(
      st.informativ === true ? [{ text: 'Abrechnung direkt mit dem KI-Anbieter, die Werte sind zur Information.' }] : [],
      KU_n(st) ? [{ text: KU_t(KU_n(st)) + ' in diesem Monat: Kosten unbekannt, sie zählen nicht zum Budget.' }] : [],
      [{ text: 'Neue Aufrufe erscheinen mit bis zu einer Stunde Verzögerung.' }],
      D.seit ? [{ text: 'Erfasst seit ' + String(D.seit) + '.' }] : []) }] };
const fn = Array.isArray(D.funktionen) ? D.funktionen : [];
const ZU = D.zustand || {};
const SP = ['name', 'aufrufe', 'tokens', 'kosten'];
const s0 = (ZU['ki-verbrauch.funktionen'] || {}).sortierung || {};
const so = { spalte: SP.includes(s0.spalte) ? s0.spalte : 'kosten', richtung: s0.richtung === 'auf' || s0.richtung === 'ab' ? s0.richtung : 'ab' };
const wert = (f, sp) => sp === 'name' ? String(f.name || f.funktion || '').toLowerCase() : sp === 'kosten' ? Number(f.usd || 0) : Number(f[sp] || 0);
const sortiert = fn.map((f, i) => [f, i]).sort((a, b) => { const x = wert(a[0], so.spalte), y = wert(b[0], so.spalte);
  const c = typeof x === 'number' ? x - y : String(x).localeCompare(String(y), 'de'); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
// Layout 13 (Plan 40, Koordinator 24.10.2026, E8/E10): 10 je Seite wie die Anzeige – „Alle markieren“ zählt dann genau die sichtbare Seite
const JE = 10;
const seiten = Math.max(1, Math.ceil(sortiert.length / JE)), bl = Math.min(seiten, Math.max(1, Number((E.seiten || {}).funktionen) || 1));
const abschnitte = [{ id: 'funktionen', titel: 'Nach Funktion', zahl: String(fn.length), offen_standard: true, inhalt: [{ typ: 'tabelle', id: 'funktionen', titel: 'Nach Funktion',
  spalten: [{ schluessel: 'name', titel: 'Funktion', sortierbar: true }, { schluessel: 'aufrufe', titel: 'Aufrufe', sortierbar: true, ausrichtung: 'rechts' },
    { schluessel: 'tokens', titel: 'Tokens', sortierbar: true, ausrichtung: 'rechts' }, { schluessel: 'kosten', titel: 'Kosten', sortierbar: true, ausrichtung: 'rechts' }],
  zeilen: sortiert.slice((bl - 1) * JE, bl * JE).map(f => ({ zellen: { name: String(f.name || f.funktion || ''), aufrufe: z(f.aufrufe, 0), tokens: z(f.tokens, 0),
    kosten: KU_alle(f) ? { text: 'Kosten unbekannt', neben: KU_t(KU_n(f)) }
      : f.eur !== null && f.eur !== undefined ? { text: z(f.eur, 2) + ' €', neben: [z(f.usd, 2) + ' US-$', KU_n(f) ? KU_dazu(KU_n(f)) : ''].filter(Boolean).join(' · ') }
      : KU_n(f) ? { text: z(f.usd, 2) + ' US-$', neben: KU_dazu(KU_n(f)) } : z(f.usd, 2) + ' US-$' } })),
  sortierung: so, seite: bl, je_seite: JE, gesamt: sortiert.length, leer: 'In diesem Monat noch keine KI-Aufrufe.' }] }];
return [{ json: { inhalt: { seite: kopf, ueberblick: knapp(ueberblick), abschnitte } } }];

// Parameter (ALLY 35, KI-Verbrauch): Sitzung für die Datenbank (nur 64 Hex-Zeichen, sonst leer = nicht angemeldet).
const E = $input.first().json;
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : ''] } }];
